"""HTTP API around the screening pipeline, so other tools can send molecules and get rankings.

Run it with ``qudock serve`` (or ``uvicorn qudock.api:app``). The screener is
trained on BACE and BBBP the first time it is needed and kept in memory.

* ``GET /health``: is the server up, and is the model trained yet
* ``POST /screen``: ``{"smiles": [...], "top": 50}`` -> ranked molecules with every readout
* ``GET /docs``: interactive documentation, generated by FastAPI
"""

from __future__ import annotations

import threading

import numpy as np
from fastapi import FastAPI, HTTPException
from pydantic import BaseModel, Field

from qudock import __version__
from qudock.data import canonical_smiles

MAX_MOLECULES = 1000

app = FastAPI(title="QuDock", version=__version__,
              description="Rank molecules for BACE-1 activity, brain penetration and "
                          "drug-likeness with a hybrid quantum kernel model.")

_lock = threading.Lock()
_screener = None


def get_screener():
    """Train once on first use; tests swap in their own with :func:`set_screener`."""
    global _screener
    with _lock:
        if _screener is None:
            from qudock.data import load_bace, load_bbbp
            from qudock.screen import Screener

            _screener = Screener().fit(load_bace(), load_bbbp())
        return _screener


def set_screener(screener) -> None:
    global _screener
    _screener = screener


class ScreenRequest(BaseModel):
    smiles: list[str] = Field(..., min_length=1, max_length=MAX_MOLECULES)
    top: int | None = Field(None, ge=1, description="return only the best N")


class Molecule(BaseModel):
    rank: int
    input: str
    smiles: str
    combined: float
    p_active: float
    activity_call: str
    activity_score: float
    bbb_probability: float
    qed: float
    pains: str
    nn_similarity: float
    in_domain: bool


class ScreenResponse(BaseModel):
    molecules: list[Molecule]
    invalid: list[str]
    model_version: str = __version__


@app.get("/health")
def health():
    return {"status": "ok", "version": __version__, "model_ready": _screener is not None}


@app.post("/screen", response_model=ScreenResponse)
def screen(request: ScreenRequest):
    parsed = [(s, canonical_smiles(s)) for s in request.smiles]
    valid = [(raw, can) for raw, can in parsed if can is not None]
    invalid = [raw for raw, can in parsed if can is None]
    if not valid:
        raise HTTPException(status_code=422, detail="none of the SMILES could be parsed")
    table = get_screener().score([can for _, can in valid])
    table.insert(0, "input", [raw for raw, _ in valid])
    table = table.sort_values("combined", ascending=False, kind="stable")
    table.insert(0, "rank", np.arange(1, len(table) + 1))
    if request.top:
        table = table.head(request.top)
    records = table.to_dict(orient="records")
    return ScreenResponse(molecules=[Molecule(**r) for r in records], invalid=invalid)
